using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
namespace CodexMeter {
static class SkinController {
    static readonly string settings=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CodexUsageFloat","skin.json");
    static TaskMonitor monitor;static bool switching;static string activeSkin;static DateTime alertUntil;
    public static Window Current {get;private set;}public static bool Running {get;private set;}
    public static TaskMonitor SharedMonitor {get{if(monitor==null)monitor=new TaskMonitor(Environment.GetEnvironmentVariable("CODEX_HOME")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".codex"));return monitor;}}
    public static void AddMenu(ContextMenu menu,string skin){
        var parent=new MenuItem{Header="皮肤"};
        foreach(string key in new[]{"capsule","ring","aurora"}){string selected=key;var item=new MenuItem{Header=key=="capsule"?"能量胶囊":key=="ring"?"立体圆环":"极光圆环",IsCheckable=true,IsChecked=skin==key};item.Click+=(s,e)=>Switch(selected);parent.Items.Add(item);}menu.Items.Add(new Separator());menu.Items.Add(parent);
    }
    static void Save(){try{Directory.CreateDirectory(Path.GetDirectoryName(settings));Data.Atomic(settings,Data.Json().Serialize(new{skin=activeSkin}));}catch{}}
    public static void Start(Application app,string initial=null){app.ShutdownMode=ShutdownMode.OnExplicitShutdown;Running=true;if(initial==null){initial="capsule";try{if(File.Exists(settings)){string value=Data.Str(Data.Get(Data.Json().DeserializeObject(File.ReadAllText(settings)),"skin"));if(value=="ring"||value=="aurora")initial=value;}}catch{}}Switch(initial);}
    public static void Switch(string skin){if(!Running){Start(Application.Current,skin);return;}if(skin==activeSkin&&Current!=null)return;
        Window old=Current;Window next=skin=="ring"?(Window)new RingWindow():skin=="aurora"?(Window)new RingWindow(false,true):new FloatWindow();
        if(old!=null){double right=old.Left+old.Width;next.Left=Math.Max(SystemParameters.VirtualScreenLeft,Math.Min(right-next.Width,SystemParameters.VirtualScreenLeft+SystemParameters.VirtualScreenWidth-next.Width));next.Top=Math.Max(SystemParameters.VirtualScreenTop,Math.Min(old.Top,SystemParameters.VirtualScreenTop+SystemParameters.VirtualScreenHeight-next.Height));}
        switching=true;try{if(old!=null)old.Close();Current=next;activeSkin=skin;Application.Current.MainWindow=next;next.Closed+=(s,e)=>{if(!switching&&Current==next){Running=false;Application.Current.Shutdown();}};next.Show();next.Activate();double remaining=(alertUntil-DateTime.UtcNow).TotalSeconds;if(remaining>0)Resume(remaining);Save();}finally{switching=false;}
    }
    static void Resume(double seconds){var c=Current as FloatWindow;if(c!=null)c.ResumeSweep(seconds);var r=Current as RingWindow;if(r!=null)r.Notify(seconds);}
    public static void NotifyActive(){alertUntil=DateTime.UtcNow.AddSeconds(3);Resume(3);}
    static bool Active(){var c=Current as FloatWindow;if(c!=null)return c.IsFlashing;var r=Current as RingWindow;return r!=null&&r.IsSweeping;}
    static void ClickSkin(string name){var root=Current.ContextMenu.Items.OfType<MenuItem>().Single(x=>(string)x.Header=="皮肤");var item=root.Items.OfType<MenuItem>().Single(x=>(string)x.Header==name);item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));}
    public static int Test(string file){var app=new Application();Start(app,"capsule");int tick=0;bool switched=false,single=false,kept=false,half=false,third=false,persisted=false;DateTime deadline=DateTime.MinValue;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(500)};timer.Tick+=(s,e)=>{try{tick++;if(tick==2){ClickSkin("立体圆环");switched=Current is RingWindow;half=Current.Width==130&&Current.Height==130&&!((RingWindow)Current).IsDark;}if(tick==3)single=app.Windows.Cast<Window>().Count(w=>w.IsVisible)==1;if(tick==4){NotifyActive();deadline=alertUntil;}if(tick==5){ClickSkin("极光圆环");third=Current is RingWindow&&((RingWindow)Current).IsDark&&Current.Width==130&&Current.Height==130;kept=Active()&&alertUntil==deadline;persisted=Data.Str(Data.Get(Data.Json().DeserializeObject(File.ReadAllText(settings)),"skin"))=="aurora";}if(tick==7){ClickSkin("能量胶囊");kept=kept&&Current is FloatWindow&&Active()&&alertUntil==deadline;}if(tick==12){timer.Stop();Data.Atomic(file,Data.Json().Serialize(new{rightClickSkinSwitched=switched,thirdSkinSwitch=third,whiteRingHalfSize=half,thirdSkinSaved=persisted,onlyOneWindow=single,alertSurvivesSwitch=kept,alertAutoStopped=!Active()}));Current.Close();}}catch(Exception ex){timer.Stop();File.WriteAllText(file,ex.ToString());app.Shutdown();}};timer.Start();app.Run();return 0;}
    public static int Preview(string file,bool demo=false){var app=new Application();var capsule=new FloatWindow(true);if(demo){var result=new{rateLimits=new{primary=new{usedPercent=39,windowDurationMins=10080,resetsAt=(long)(DateTime.UtcNow.AddDays(3).AddHours(12)-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds}}};capsule.SetPreviewQuota(Data.Json().DeserializeObject(Data.Json().Serialize(result)));}else capsule.LoadPreviewQuota();var white=new RingWindow(true);white.ApplyData(capsule.CurrentQuota,false,DateTime.Now);var aurora=new RingWindow(true,true);aurora.ApplyData(capsule.CurrentQuota,false,DateTime.Now);Window[] windows={capsule,white,aurora};string[] names={"能量胶囊","立体圆环 × 0.5","极光圆环"};foreach(var w in windows){w.Show();w.UpdateLayout();}double width=windows.Sum(w=>w.ActualWidth)+80,height=315;var visual=new System.Windows.Media.DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(237,240,245)),null,new Rect(0,0,width,height));double x=20;for(int i=0;i<windows.Length;i++){var w=windows[i];dc.DrawText(new System.Windows.Media.FormattedText(names[i],System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new System.Windows.Media.Typeface("Microsoft YaHei UI"),12,System.Windows.Media.Brushes.DimGray,1.0),new Point(x,14));dc.DrawRectangle(new System.Windows.Media.VisualBrush(w),null,new Rect(x,45+(260-w.ActualHeight)/2,w.ActualWidth,w.ActualHeight));x+=w.ActualWidth+20;}}var bmp=new System.Windows.Media.Imaging.RenderTargetBitmap((int)(width*2),(int)(height*2),192,192,System.Windows.Media.PixelFormats.Pbgra32);bmp.Render(visual);var e=new System.Windows.Media.Imaging.PngBitmapEncoder();e.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bmp));using(var f=File.Create(file))e.Save(f);foreach(var w in windows)w.Close();return 0;}
}
}
